package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var hpY, atkY, defY int
	var hpM, atkM, defM int
	var hpCost, atkCost, defCost int

	fmt.Fscan(in, &hpY, &atkY, &defY)
	fmt.Fscan(in, &hpM, &atkM, &defM)
	fmt.Fscan(in, &hpCost, &atkCost, &defCost)

	maxAtk := defM + hpM
	if atkY > maxAtk {
		maxAtk = atkY
	}

	maxDef := atkM
	if defY > maxDef {
		maxDef = defY
	}

	answer := int(^uint(0) >> 1)

	for atk := atkY; atk <= maxAtk; atk++ {
		damageToMonster := atk - defM
		if damageToMonster <= 0 {
			continue
		}

		turns := (hpM + damageToMonster - 1) / damageToMonster

		for def := defY; def <= maxDef; def++ {
			damageToYang := atkM - def
			if damageToYang < 0 {
				damageToYang = 0
			}

			requiredHP := turns*damageToYang + 1
			hpUpgrade := requiredHP - hpY
			if hpUpgrade < 0 {
				hpUpgrade = 0
			}

			cost := hpUpgrade*hpCost +
				(atk-atkY)*atkCost +
				(def-defY)*defCost

			if cost < answer {
				answer = cost
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var hpY, atkY, defY int
	var hpM, atkM, defM int
	var hCost, aCost, dCost int

	fmt.Fscan(in, &hpY, &atkY, &defY)
	fmt.Fscan(in, &hpM, &atkM, &defM)
	fmt.Fscan(in, &hCost, &aCost, &dCost)

	minCost := int(1e9)
	maxAtk := max(atkY, defM+hpM)
	maxDef := max(defY, atkM)

	for atk := atkY; atk <= maxAtk; atk++ {
		damageToMonster := atk - defM
		if damageToMonster <= 0 {
			continue
		}

		turns := (hpM + damageToMonster - 1) / damageToMonster

		for def := defY; def <= maxDef; def++ {
			damageToYang := max(0, atkM-def)
			requiredHP := turns*damageToYang + 1
			boughtHP := max(0, requiredHP-hpY)

			cost := boughtHP*hCost +
				(atk-atkY)*aCost +
				(def-defY)*dCost

			if cost < minCost {
				minCost = cost
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, minCost)
}

